    startButtonPrev : BOOL := FALSE; // Rising edge detection for Start button
    tmpRisingEdge : BOOL;
    waitingForStart : BOOL := FALSE; // TRUE = waiting for Start press to advance
END_VAR"}, {"old":"    // Emergency stop has highest priority - stops all outputs
    IF EmergencyStop = FALSE THEN
        MoveDown := FALSE;
        MoveUp := FALSE;
        MoveLeft := FALSE;
        MoveRight := FALSE;
        ActivateGrip := FALSE;
        ActivateRelease := FALSE;
    ELSIF SingleStepMode THEN
        // Detect rising edge on Start button
        tmpRisingEdge := Start AND NOT startButtonPrev;
        startButtonPrev := Start;

        IF tmpRisingEdge THEN
            stepIndex := stepIndex + 1;
            IF stepIndex > 7 THEN
                stepIndex := 0;
            END_IF;
        END_IF;

        // Execute current step
        CASE stepIndex OF
            0: // Down
                MoveDown := TRUE;
                IF DownLimitSwitch THEN
                    stepIndex := 1;
                END_IF;
            1: // Grip
                ActivateGrip := TRUE;
                IF GripLimitSwitch THEN
                    stepIndex := 2;
                END_IF;
            2: // Up
                MoveUp := TRUE;
                IF UpLimitSwitch THEN
                    stepIndex := 3;
                END_IF;
            3: // Right
                MoveRight := TRUE;
                IF RightLimitSwitch THEN
                    stepIndex := 4;
                END_IF;
            4: // Down (second descent)
                MoveDown := TRUE;
                IF DownLimitSwitch THEN
                    stepIndex := 5;
                END_IF;
            5: // Release
                ActivateRelease := TRUE;
                IF ReleaseLimitSwitch THEN
                    stepIndex := 6;
                END_IF;
            6: // Up (second ascent)
                MoveUp := TRUE;
                IF UpLimitSwitch THEN
                    stepIndex := 7;
                END_IF;
            7: // Left (return to start)
                MoveLeft := TRUE;
                IF LeftLimitSwitch THEN
                    stepIndex := 0;
                END_IF;
        END_CASE;", "new":"    // Emergency stop has highest priority - stops all outputs
