        // Reset step index when entering this mode
        stepIndex := 0;

        // Reset all outputs to prevent carryover from previous scans
        MoveDown := FALSE;
        MoveUp := FALSE;
        MoveLeft := FALSE;
        MoveRight := FALSE;
        ActivateGrip := FALSE;
        ActivateRelease := FALSE;

        // Detect rising edge on Start button
        tmpRisingEdge := Start AND NOT startButtonPrev;
